import React from 'react';
import { Link } from 'gatsby';
import PropTypes from 'prop-types';
import { navLinks } from '@config';
import ThemeToggle from './themeToggle';
import styled from 'styled-components';
import { theme, mixins, media, tokens } from '@styles';
const { colors, fontSizes, fonts } = theme;

const StyledClip = styled.div`
  position: fixed;
  top: 0;
  bottom: 0;
  right: 0;
  width: 100%;
  height: 100vh;
  z-index: 10;
  overflow: hidden;
  /* establishes a containing block for the fixed child below, so its
     off-screen translateX never leaks into the document's scroll width */
  transform: translateZ(0);
  /* this wrapper spans the full viewport even when the menu is closed;
     without this it silently blocks taps on whatever's underneath it */
  pointer-events: none;
  display: none;
  ${media.tablet`display: block;`};
`;
const StyledContainer = styled.div`
  position: fixed;
  top: 0;
  bottom: 0;
  right: 0;
  width: 100%;
  height: 100%;
  outline: 0;
  pointer-events: auto;
  transition: ${theme.transition};
  transform: translateX(${props => (props.menuOpen ? 0 : 100)}%);
  visibility: ${props => (props.menuOpen ? 'visible' : 'hidden')};
`;
const Sidebar = styled.aside`
  ${mixins.flexCenter};
  flex-direction: column;
  background-color: ${tokens.paperAlt};
  padding: 50px;
  width: 50vw;
  height: 100%;
  position: relative;
  right: 0;
  margin-left: auto;
  font-family: ${fonts.Calibre};
  box-shadow: -10px 0px 30px -18px rgba(var(--shadow-rgb), 0.3);
  ${media.thone`padding: 25px;`};
  ${media.phablet`width: 75vw;`};
  ${media.tiny`padding: 10px;`};
`;
const NavLinks = styled.nav`
  ${mixins.flexBetween};
  width: 100%;
  flex-direction: column;
  text-align: center;
  color: ${tokens.ink};
`;
const NavList = styled.ol`
  padding: 0;
  margin: 0;
  list-style: none;
  width: 100%;
`;
const NavListItem = styled.li`
  margin: 0 auto 20px;
  position: relative;
  font-size: ${fontSizes.lg};
  ${media.thone`
    margin: 0 auto 10px;
    font-size: ${fontSizes.md};
  `};
  ${media.tiny`font-size: ${fontSizes.smish};`};
`;
const NavLink = styled(Link)`
  ${mixins.link};
  padding: 3px 20px 20px;
  width: 100%;
`;

const Menu = ({ menuOpen, toggleMenu }) => {
  const handleMenuClick = e => {
    const target = e.target;
    const isLink = target.hasAttribute('href');
    const isNotMenu = target.classList && target.classList[0].includes('StyledContainer');

    if (isLink || isNotMenu) {
      toggleMenu();
    }
  };

  return (
    <StyledClip>
      <StyledContainer
        menuOpen={menuOpen}
        onClick={handleMenuClick}
        aria-hidden={!menuOpen}
        tabIndex={menuOpen ? 1 : -1}>
        <Sidebar>
          <NavLinks>
            <NavList>
              {navLinks &&
                navLinks.map(({ url, name }, i) => (
                  <NavListItem key={i}>
                    <NavLink to={url}>{name}</NavLink>
                  </NavListItem>
                ))}
            </NavList>
            <div style={{ marginTop: 30, display: 'flex', justifyContent: 'center' }}>
              <ThemeToggle />
            </div>
          </NavLinks>
        </Sidebar>
      </StyledContainer>
    </StyledClip>
  );
};

Menu.propTypes = {
  menuOpen: PropTypes.bool.isRequired,
  toggleMenu: PropTypes.func.isRequired,
};

export default Menu;
